   bool m_allowUndo;
   bool m_writeFailed;
   bool m_notifyFolderLoaded;
-  nsCString m_newMsgKeywords;  // TODO: Remove. CopyFileMessage() only.
+  nsCString m_newMsgKeywords;
   nsCOMPtr<nsIMsgDBHdr> m_newHdr;
 };
